export const savePersonnelReport = async (report: PersonnelReport) => {
    // 1. Save current report (Daily/Weekly/Monthly)
    await setDoc(doc(db, "personnel_reports", report.id), sanitizeData(report));

    // 2. Logic for automatic weekly/monthly population if it's a daily report
    if (report.type === 'daily') {
        const dateObj = new Date(report.date);
        const weekIdStr = getWeekNumber(dateObj);
        const monthIdStr = report.date.substring(0, 7); // YYYY-MM

        // Auto-handle Weekly
        await syncSubReport(report, 'weekly', weekIdStr);
        // Auto-handle Monthly
        await syncSubReport(report, 'monthly', monthIdStr);
    }
};

const syncSubReport = async (dailyReport: PersonnelReport, subType: 'weekly' | 'monthly', subDate: string) => {
    const reportId = `rep-${dailyReport.userId}-${subType}-${subDate}`;
    const reportRef = doc(db, "personnel_reports", reportId);
    const snap = await getDoc(reportRef);

    const newItems = dailyReport.items.map(item => ({
        ...item,
        id: `auto-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        text: `[${dailyReport.date}] ${item.text}` // Prefix with date to distinguish
    }));

    if (snap.exists()) {
        const existingData = snap.data() as PersonnelReport;
        const updatedItems = [...existingData.items, ...newItems];
        await updateDoc(reportRef, { items: updatedItems, updatedAt: new Date().toISOString() });
    } else {
        const newSubReport: PersonnelReport = {
            id: reportId,
            userId: dailyReport.userId,
            userName: dailyReport.userName,
            date: subDate,
            type: subType,
            items: newItems,
            createdAt: new Date().toISOString()
        };
        await setDoc(reportRef, sanitizeData(newSubReport));
    }
};

