export const sanitizeData = (data: any): any => {
  const seen = new WeakSet();
  const deepCopy = (obj: any): any => {
    if (obj === undefined || obj === null) return null;
    if (typeof obj !== 'object') return obj;
    if (obj instanceof Date) return obj.toISOString();
    if (seen.has(obj)) return null;
    seen.add(obj);
    if (Array.isArray(obj)) {
      return obj.map(deepCopy).filter(item => item !== undefined);
    }
    const proto = Object.getPrototypeOf(obj);
    if (proto && proto.constructor && proto.constructor.name !== 'Object') {
        if (proto !== null) return null;
    }
    if (obj._reactName || (obj.nativeEvent && obj.target) || (obj.nodeType && obj.nodeName) || (obj.i && obj.src)) {
        return null;
    }
    const res: any = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        if (key.startsWith('_') || key === 'src' || key === 'target' || key === 'view' || key === 'nativeEvent' || key === 'rawFile') continue;
        try {
            const val = deepCopy(obj[key]);
            if (val !== undefined) res[key] = val;
        } catch (e) { res[key] = null; }
      }
    }
    return res;
  };
  try { return deepCopy(data); } catch (e) { return null; }
};

export const compressImage = (file: File, maxWidth = 800, quality = 0.5): Promise<string> => {
    return new Promise((resolve, reject) => {
        if (!file.type.startsWith('image/')) return resolve("");
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                if (width > maxWidth) { height *= maxWidth / width; width = maxWidth; }
                canvas.width = width; canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(img, 0, 0, width, height);
                    const dataUrl = canvas.toDataURL('image/jpeg', quality);
                    resolve(dataUrl);
                } else resolve(event.target?.result as string);
            };
            img.onerror = () => resolve(""); 
        };
        reader.onerror = () => resolve("");
    });
};

const fileToDataURL = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
};

export const uploadFileWithProgress = async (file: File, onProgress: (progress: number) => void, onSuccess: (url: string) => void, onError: (error: Error) => void) => {
    if (file.type.startsWith('image/')) {
        try {
            onProgress(20); const base64 = await compressImage(file, 800, 0.5); onProgress(60);
            if (base64) { setTimeout(() => { onProgress(100); onSuccess(base64); }, 300); return; }
        } catch (e) { console.error("Compression failed", e); }
    }
    if (file.type === 'application/pdf' && file.size < 2 * 1024 * 1024) {
        try { onProgress(30); const base64 = await fileToDataURL(file); onProgress(100); onSuccess(base64); return; } catch (e) {}
    }
    const dateFolder = new Date().toISOString().split('T')[0];
    const safeName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
    const storageRef = ref(storage, `uploads/${dateFolder}/${Date.now()}_${safeName}`);
    const uploadTask = uploadBytesResumable(storageRef, file);
    const watchdog = setTimeout(() => { if (uploadTask.snapshot.bytesTransferred === 0) { uploadTask.cancel(); onError(new Error("آپلود کند است یا دسترسی مسدود شده است.")); } }, 15000);
    uploadTask.on('state_changed', (snapshot) => { const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100; onProgress(progress); if (progress > 0) clearTimeout(watchdog); }, (error) => { clearTimeout(watchdog); onError(new Error("آپلود ناموفق. لطفاً اتصال اینترنت را بررسی کنید.")); }, () => { clearTimeout(watchdog); getDownloadURL(uploadTask.snapshot.ref).then((downloadURL) => onSuccess(downloadURL)); });
};

export const backupSystemData = async () => {
    try {
        const collections = ['tickets', 'customers', 'settings', 'messages', 'tasks', 'meetings', 'kpis', 'custom_forms', 'sales_records', 'personnel_reports'];
        const data: any = {};
        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            data[col] = snap.docs.map(d => d.data());
        }
        const safeData = sanitizeData(data);
        const blob = new Blob([JSON.stringify(safeData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `CRM_Backup_${new Date().toISOString().split('T')[0]}.json`; a.click(); URL.revokeObjectURL(url);
        return true;
    } catch (e) { return false; }
};

