export const savePersonnelToCloud = async (personnel: Personnel[]) => {
    const cleanList = personnel.map(p => {
        const cleanDocs = (p.documents || []).map(docItem => {
             const cleanedFiles = cleanFilesForDB([docItem.file]);
             return cleanedFiles.length > 0 ? { ...docItem, file: cleanedFiles[0] } : null;
        }).filter(d => d !== null);
        return { ...p, documents: cleanDocs };
    });
    await setDoc(doc(db, "settings", "personnel"), { list: sanitizeData(cleanList) });
    logSystemAction('UPDATE', 'Personnel', `لیست پرسنل بروزرسانی شد`, 'Admin');
};

export const subscribeToSettings = (onConfig: (c: AppConfig) => void, onServices: (s: ServiceOption[]) => void, onPersonnel: (p: Personnel[]) => void) => {
    return onSnapshot(collection(db, "settings"), (snap) => {
        snap.docs.forEach(doc => {
            if (doc.id === 'appConfig') onConfig(doc.data() as AppConfig);
            if (doc.id === 'services') onServices(doc.data().list);
            if (doc.id === 'personnel') onPersonnel(doc.data().list);
        });
    });
};

import React, { useState, useEffect } from 'react';
import { Personnel, PersonnelReport, ReportItem, ReportType } from '../types';
import { IconCheck, IconPlus, IconTrash, IconCalendar, IconList, IconRefreshCw, IconAward, IconActivity } from './Icons';
import { savePersonnelReport, subscribeToPersonnelReports, updateReportInCloud } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  lang: Language;
}

export const PersonnelReporting: React.FC<Props> = ({ currentUser, lang }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('daily');
  const [reports, setReports] = useState<PersonnelReport[]>([]);
  const [currentDate, setCurrentDate] = useState(new Date().toISOString().split('T')[0]);
  const [newItems, setNewItems] = useState<string[]>(['']);

  const t = {
      fa: {
          header: 'سیستم گزارش‌دهی پرسنل',
          sub: 'ثبت فعالیت‌های روزانه، پایش هفتگی و ماهانه',
          daily: 'گزارش روزانه',
          weekly: 'گزارش هفتگی',
          monthly: 'گزارش ماهانه',
          addItem: 'افزودن ردیف',
          submit: 'ثبت و ارسال گزارش',
          history: 'سوابق گزارش‌ها',
          empty: 'هنوز موردی ثبت نشده است.',
          autoNote: 'این گزارش به صورت خودکار از گزارش‌های روزانه تجمیع شده است اما می‌توانید آن را ویرایش کنید.',
          placeholder: 'شرح فعالیت...',
          success: 'گزارش با موفقیت ثبت شد.',
          sync: 'بروزرسانی تیک‌ها'
      },
      en: {
          header: 'Personnel Reporting System',
          sub: 'Daily activities, weekly and monthly tracking',
          daily: 'Daily Report',
          weekly: 'Weekly Report',
          monthly: 'Monthly Report',
          addItem: 'Add Line',
          submit: 'Submit Report',
          history: 'Report History',
          empty: 'No records found.',
          autoNote: 'This report is auto-generated from daily inputs but you can edit it.',
          placeholder: 'Activity description...',
          success: 'Report submitted successfully.',
          sync: 'Sync Checkboxes'
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToPersonnelReports(currentUser.id, setReports);
      return () => unsub();
  }, [currentUser.id]);

  const handleAddItem = () => setNewItems([...newItems, '']);
  const handleRemoveItem = (index: number) => setNewItems(newItems.filter((_, i) => i !== index));
  const handleItemChange = (index: number, val: string) => {
      const updated = [...newItems];
      updated[index] = val;
      setNewItems(updated);
  };

  const handleSubmitDaily = async () => {
      const items: ReportItem[] = newItems
        .filter(text => text.trim() !== '')
        .map(text => ({
            id: `item-${Date.now()}-${Math.random()}`,
            text: text.trim(),
            isCompleted: true
        }));

      if (items.length === 0) return;

      const report: PersonnelReport = {
          id: `rep-${currentUser.id}-daily-${currentDate}`,
          userId: currentUser.id,
          userName: currentUser.fullName,
          date: currentDate,
          type: 'daily',
          items,
          createdAt: new Date().toISOString()
      };

      await savePersonnelReport(report);
      setNewItems(['']);
      alert(t.success);
  };

  const toggleItemCompletion = async (report: PersonnelReport, itemId: string) => {
      const updatedItems = report.items.map(item => 
          item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item
      );
      await updateReportInCloud(report.id, updatedItems);
  };

  const currentReport = reports.find(r => r.type === activeTab && (
      activeTab === 'daily' ? r.date === currentDate :
      activeTab === 'monthly' ? r.date === currentDate.substring(0, 7) :
      false // Weekly logic needs ISO calc, simpler for now to show list
  ));

  return (
    <div className="space-y-6 animate-fade-in">
        {/* Header */}
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div>
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <div className="bg-indigo-100 text-indigo-600 p-2 rounded-lg"><IconActivity className="w-6 h-6" /></div>
                    {t.header}
                </h2>
                <p className="text-sm text-gray-500 mt-1">{t.sub}</p>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-xl">
                {(['daily', 'weekly', 'monthly'] as ReportType[]).map(tab => (
                    <button 
                        key={tab}
                        onClick={() => setActiveTab(tab)}
                        className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === tab ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        {t[tab]}
                    </button>
                ))}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Input Form (Only for Daily) */}
            <div className="lg:col-span-1">
                {activeTab === 'daily' ? (
                    <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-md sticky top-24">
                        <div className="flex items-center gap-2 mb-6 pb-4 border-b border-gray-50">
                            <IconCalendar className="text-indigo-500" />
                            <input 
                                type="date" 
                                className="font-bold text-gray-700 outline-none bg-transparent"
                                value={currentDate}
                                onChange={e => setCurrentDate(e.target.value)}
                            />
                        </div>
                        <div className="space-y-3 mb-6">
                            {newItems.map((item, idx) => (
                                <div key={idx} className="flex gap-2 group">
                                    <input 
                                        className="flex-grow bg-gray-50 border border-gray-200 rounded-xl px-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-100 transition-all"
                                        placeholder={t.placeholder}
                                        value={item}
                                        onChange={e => handleItemChange(idx, e.target.value)}
                                    />
                                    {newItems.length > 1 && (
                                        <button onClick={() => handleRemoveItem(idx)} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4"/></button>
                                    )}
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-3">
                            <button onClick={handleAddItem} className="w-full py-2 border-2 border-dashed border-gray-200 text-gray-400 rounded-xl text-sm font-bold hover:border-indigo-300 hover:text-indigo-500 transition-all flex items-center justify-center gap-2">
                                <IconPlus className="w-4 h-4" /> {t.addItem}
                            </button>
                            <button onClick={handleSubmitDaily} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-transform active:scale-95">
                                {t.submit}
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100 shadow-sm text-amber-800 leading-relaxed text-sm">
                        <div className="flex items-center gap-2 font-bold mb-2"><IconActivity className="w-5 h-5" /> هوشمندی سیستم:</div>
                        {t.autoNote}
                    </div>
                )}
            </div>

            {/* List and Checkboxes */}
            <div className="lg:col-span-2 space-y-4">
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                    <div className="p-4 bg-gray-50 border-b border-gray-100 font-bold text-gray-700 flex justify-between items-center">
                        <span className="flex items-center gap-2"><IconList className="w-5 h-5 text-indigo-500" /> {t.history}</span>
                        <span className="text-xs bg-white px-2 py-1 rounded border border-gray-200">{activeTab.toUpperCase()}</span>
                    </div>
                    <div className="divide-y divide-gray-50 max-h-[600px] overflow-y-auto">
                        {reports.filter(r => r.type === activeTab).sort((a,b) => b.date.localeCompare(a.date)).map(report => (
                            <div key={report.id} className="p-6 hover:bg-gray-50/50 transition-colors">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="font-black text-indigo-900 flex items-center gap-2">
                                        <div className="w-2 h-2 rounded-full bg-indigo-400"></div>
                                        {report.date}
                                    </h4>
                                    <span className="text-[10px] text-gray-400 dir-ltr">Last update: {new Date(report.updatedAt || report.createdAt).toLocaleTimeString()}</span>
                                </div>
                                <div className="space-y-2">
                                    {report.items.map(item => (
                                        <div 
                                            key={item.id} 
                                            onClick={() => toggleItemCompletion(report, item.id)}
                                            className="flex items-center gap-3 p-3 bg-white border border-gray-100 rounded-xl cursor-pointer group hover:border-indigo-200 transition-all shadow-sm"
                                        >
                                            <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${item.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200'}`}>
                                                {item.isCompleted && <IconCheck className="w-4 h-4" />}
                                            </div>
                                            <span className={`text-sm flex-grow ${item.isCompleted ? 'text-gray-400 line-through' : 'text-gray-700 font-medium'}`}>{item.text}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                        {reports.filter(r => r.type === activeTab).length === 0 && (
                            <div className="p-12 text-center text-gray-400 italic">{t.empty}</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

